 * Helpers for reading and interpreting Codex JSONL rollout transcripts.
 */

import * as fs from 'fs';
import type { ContentBlock, RolloutLine } from './types';

const NANOSECONDS_PER_MS = 1e6;

/**
 * Reads a JSONL transcript file from disk and returns an array of parsed
 * RolloutLine records (one per non-empty line).
 */
export function readTranscript(filePath: string): RolloutLine[] {
  const content = fs.readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim().length > 0)
    .map((line) => JSON.parse(line) as RolloutLine);
}

/**
 * Parses an ISO 8601 timestamp string into a nanosecond integer.
 * Returns null for null, undefined, or empty string inputs (or unparseable values).
 */
export function parseTimestampToNs(input: string | null | undefined): number | null {
  if (input == null || input === '') {
    return null;
  }
  const ms = Date.parse(input);
  if (Number.isNaN(ms)) {
    return null;
  }
  return ms * NANOSECONDS_PER_MS;
}

/**
 * Extracts plain text from a content-block array (joining entries with '\n'),
 * returns a string argument unchanged, and returns '' for undefined.
 */
export function extractTextFromContent(
  content: ContentBlock[] | string | undefined,
): string {
  if (content === undefined) {
    return '';
  }
  if (typeof content === 'string') {
    return content;
  }
  return content
    .filter((block) => typeof block?.text === 'string')
    .map((block) => block.text)
    .join('\n');
}

/**
 * Returns an object with a `text` property containing the last user message
 * text found in the transcript, or null if none exists.
 */
export function findLastUserPrompt(records: RolloutLine[]): { text: string } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const payload = records[i].payload;
    if (payload.role === 'user') {
      return { text: extractTextFromContent(payload.content) };
    }
  }
  return null;
}

/**
 * Returns the subset of records belonging to the most recent turn — from the
 * task_started event_msg through the task_complete event_msg, inclusive.
 */
export function getLastTurnRecords(records: RolloutLine[]): RolloutLine[] {
  let startIdx = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    const rec = records[i];
    if (rec.type === 'event_msg' && rec.payload.type === 'task_started') {
      startIdx = i;
      break;
    }
  }

  if (startIdx === -1) {
    return [];
  }

  let endIdx = records.length - 1;
  for (let i = startIdx; i < records.length; i++) {
    const rec = records[i];
    if (rec.type === 'event_msg' && rec.payload.type === 'task_complete') {
      endIdx = i;
      break;
    }
  }

  return records.slice(startIdx, endIdx + 1);
}

/**
 * Finds the token_count event in the transcript and returns an object with
 * input_tokens, output_tokens, and total_tokens. Returns null if no token
 * count event is found.
 */
export function getTokenUsage(
  records: RolloutLine[],
): { input_tokens: number; output_tokens: number; total_tokens: number } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const rec = records[i];
    if (rec.type === 'event_msg' && rec.payload.type === 'token_count') {
      const info = (rec.payload.info ?? {}) as Record<string, unknown>;
      // Codex nests cumulative usage under `total_token_usage`; fall back to
      // `last_token_usage` and finally the info object itself.
      const usage = (info.total_token_usage ??
        info.last_token_usage ??
        info) as Record<string, unknown>;
      return {
        input_tokens: Number(usage.input_tokens ?? 0),
        output_tokens: Number(usage.output_tokens ?? 0),
        total_tokens: Number(usage.total_tokens ?? 0),
      };
    }
  }
  return null;
}

/**
 * Returns the model name from the session_meta record, or 'unknown' when no
 * model is present in the session metadata.
 */
export function getModel(records: RolloutLine[]): string {
  for (const rec of records) {
    if (rec.type === 'session_meta') {
      const payload = rec.payload as Record<string, unknown>;
      const meta = (payload.meta ?? {}) as Record<string, unknown>;
      const info = (payload.info ?? {}) as Record<string, unknown>;
      const model = payload.model ?? meta.model ?? info.model;
      if (typeof model === 'string' && model.length > 0) {
        return model;
      }
      return 'unknown';
    }
  }
  return 'unknown';
}

/**
 * Returns the session ID from the session_meta record in the transcript.
 */
export function getSessionId(records: RolloutLine[]): string {
  for (const rec of records) {
    if (rec.type === 'session_meta') {
      const payload = rec.payload as Record<string, unknown>;
      const meta = (payload.meta ?? {}) as Record<string, unknown>;
      const id = payload.id ?? meta.id;
      if (typeof id === 'string') {
        return id;
      }
    }
  }
  return '';
}

/**
 * Converts a function_call_output payload's `output` field into a plain string.
 */
export function outputToString(output: unknown): string {
  if (output == null) {
    return '';
  }
  if (typeof output === 'string') {
    return output;
  }
  const obj = output as Record<string, unknown>;
  if (typeof obj.content === 'string') {
    return obj.content;
  }
  if (Array.isArray(obj.content)) {
    return extractTextFromContent(obj.content as ContentBlock[]);
  }
  if (typeof obj.output === 'string') {
    return obj.output;
  }
  return JSON.stringify(output);
}

/**
 * Builds a map from call_id strings to tool output strings by scanning
 * function_call_output records. Returns an empty object if no tool outputs
 * are present.
 */
export function buildToolResultMap(records: RolloutLine[]): Record<string, string> {
  const result: Record<string, string> = {};
  for (const rec of records) {
    if (rec.payload.type === 'function_call_output') {
      const callId = rec.payload.call_id;
      if (typeof callId === 'string') {
        result[callId] = outputToString(rec.payload.output);
      }
    }
  }
  return result;
}
