AAC,CAAC,oBAAoB,CAAC,EAAE,OAAO,EAAE,CAAC,EAAE,OAAO,EAAE,EAAE,IAAI,EAAE,WAAW,EAAE,OAAO,EAAE,YAAY,EAAE,EAAE,CAAC,EAAE,CAAC,CAAC;IAC3H,MAAM,CAAC,SAAS,CAAC,aAAa,CAAC,sBAAsB,CAAC,CAAC,CAAC,IAAI,CAAC,KAAK,CAAC,CAAC;IACpE,MAAM,CAAC,SAAS,CAAC,aAAa,CAAC,mBAAmB,CAAC,CAAC,CAAC,WAAW,EAAE,CAAC;IACnE,MAAM,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,gBAAgB,EAAE,CAAC;AAC9C,CAAC,CAAC,CAAC;AAEH,IAAI,CAAC,6CAA6C,EAAE,KAAK,IAAI,EAAE;IAC7D,MAAM,IAAI,GAAG,OAAO,CAAC,cAAc,CAAC,CAAC;IACrC,IAAI,CAAC,WAAW,CAAC,SAAS,EAAE,CAAC;IAC7B,MAAM,OAAO,GAAQ,EAAE,IAAI,EAAE,GAAG,EAAE,WAAW,EAAE,GAAG,EAAE,SAAS,EAAE,GAAG,EAAE,GAAG,EAAE,GAAG,EAAE,MAAM,EAAE,GAAG,EAAE,gBAAgB,EAAE,EAAE,EAAE,wBAAwB,EAAE,GAAG,EAAE,CAAC;IACjJ,MAAM,EAAE,CAAC,aAAa,CAAC,OAAO,CAAC,CAAC;IAChC,MAAM,CAAC,SAAS,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,CAAC,CAAC,CAAC;IACjC,MAAM,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,GAAG,CAAC,gBAAgB,EAAE,CAAC;AAClD,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/codex/tests_scratch/scratch.test.ts"],"sourcesContent":["/* eslint-disable */\nimport * as fs from 'fs';\nimport * as os from 'os';\nimport * as path from 'path';\n\nconst spanCalls: any[] = [];\nfunction makeSpan(id: string) {\n  return {\n    traceId: 'trace-1',\n    spanId: id,\n    setOutputs: jest.fn(),\n    setStatus: jest.fn(),\n    setAttribute: jest.fn(),\n    end: jest.fn(),\n  };\n}\nlet counter = 0;\nconst traceInfo: any = { traceMetadata: {} };\n\njest.mock('@mlflow/core', () => ({\n  init: jest.fn(),\n  startSpan: jest.fn((opts: any) => {\n    const span = makeSpan(`span-${counter++}`);\n    spanCalls.push({ opts, span });\n    return span;\n  }),\n  flushTraces: jest.fn().mockResolvedValue(undefined),\n  SpanType: { LLM: 'LLM', TOOL: 'TOOL', AGENT: 'AGENT' },\n  SpanStatusCode: { ERROR: 'STATUS_CODE_ERROR', OK: 'STATUS_CODE_OK' },\n  TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n  InMemoryTraceManager: { getInstance: () => ({ getTrace: () => ({ info: traceInfo }) }) },\n}));\n\nimport * as t from '../src/transcript';\nimport * as tr from '../src/tracing';\n\nbeforeEach(() => {\n  spanCalls.length = 0;\n  counter = 0;\n  traceInfo.traceMetadata = {};\n});\n\ntest('parseTimestampToNs', () => {\n  expect(t.parseTimestampToNs(null)).toBeNull();\n  expect(t.parseTimestampToNs(undefined)).toBeNull();\n  expect(t.parseTimestampToNs('')).toBeNull();\n  const ns = t.parseTimestampToNs('2026-07-06T00:00:00.000Z');\n  expect(ns).toBeGreaterThan(0);\n  expect(ns).toBe(Date.parse('2026-07-06T00:00:00.000Z') * 1e6);\n});\n\ntest('extractTextFromContent', () => {\n  expect(t.extractTextFromContent(undefined)).toBe('');\n  expect(t.extractTextFromContent('hi')).toBe('hi');\n  expect(t.extractTextFromContent([{ type: 'input_text', text: 'a' }, { type: 'input_text', text: 'b' }])).toBe('a\\nb');\n});\n\ntest('readTranscript', () => {\n  const p = path.join(os.tmpdir(), `scratch-${Date.now()}.jsonl`);\n  fs.writeFileSync(p, '{\"timestamp\":\"t\",\"type\":\"event_msg\",\"payload\":{\"type\":\"x\"}}\\n\\n{\"timestamp\":\"t2\",\"type\":\"response_item\",\"payload\":{\"type\":\"message\"}}\\n');\n  const recs = t.readTranscript(p);\n  expect(recs.length).toBe(2);\n  expect(recs[0].payload.type).toBe('x');\n  fs.unlinkSync(p);\n});\n\nconst turn: any[] = [\n  { timestamp: '2026-07-06T00:00:00Z', type: 'event_msg', payload: { type: 'task_started' } },\n  { timestamp: '2026-07-06T00:00:01Z', type: 'response_item', payload: { type: 'message', role: 'user', content: [{ type: 'input_text', text: 'hello' }] } },\n  { timestamp: '2026-07-06T00:00:02Z', type: 'response_item', payload: { type: 'function_call', name: 'shell', call_id: 'c1', arguments: '{\"cmd\":\"ls\"}' } },\n  { timestamp: '2026-07-06T00:00:03Z', type: 'event_msg', payload: { type: 'exec_command_end', call_id: 'c1', exit_code: 0, status: 'completed' } },\n  { timestamp: '2026-07-06T00:00:04Z', type: 'response_item', payload: { type: 'function_call_output', call_id: 'c1', output: 'file1\\nfile2' } },\n  { timestamp: '2026-07-06T00:00:05Z', type: 'response_item', payload: { type: 'function_call', name: 'shell', call_id: 'c2', arguments: '{\"cmd\":\"bad\"}' } },\n  { timestamp: '2026-07-06T00:00:06Z', type: 'event_msg', payload: { type: 'exec_command_end', call_id: 'c2', exit_code: 2, status: 'failed' } },\n  { timestamp: '2026-07-06T00:00:07Z', type: 'response_item', payload: { type: 'function_call_output', call_id: 'c2', output: 'boom' } },\n  { timestamp: '2026-07-06T00:00:08Z', type: 'response_item', payload: { type: 'message', role: 'assistant', content: [{ type: 'output_text', text: 'done' }] } },\n  { timestamp: '2026-07-06T00:00:09Z', type: 'event_msg', payload: { type: 'token_count', info: { total_token_usage: { input_tokens: 10, output_tokens: 5, total_tokens: 15 } } } },\n  { timestamp: '2026-07-06T00:00:10Z', type: 'event_msg', payload: { type: 'task_complete' } },\n];\n\ntest('turn helpers', () => {\n  expect(t.getLastTurnRecords(turn)[0].type).toBe('event_msg');\n  expect(t.getLastTurnRecords(turn)[0].payload.type).toBe('task_started');\n  expect(t.getTokenUsage(turn)).toEqual({ input_tokens: 10, output_tokens: 5, total_tokens: 15 });\n  expect(t.findLastUserPrompt(turn)).toEqual({ text: 'hello' });\n  expect(t.buildToolResultMap(turn)).toEqual({ c1: 'file1\\nfile2', c2: 'boom' });\n  expect(tr.buildToolStatuses(turn)).toEqual({ c1: { failed: false, exitCode: 0 }, c2: { failed: true, exitCode: 2 } });\n  const started = tr.findTaskStartedNs(turn)!;\n  const complete = tr.findTaskCompleteNs(turn)!;\n  expect(started).toBeGreaterThan(0);\n  expect(complete).toBeGreaterThan(started);\n});\n\ntest('reconstructMessages skips empty and maps roles', () => {\n  const items: any[] = [\n    { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'developer', content: 'sys' } },\n    { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'user', content: '  ' } },\n    { timestamp: 't', type: 'response_item', payload: { type: 'function_call', name: 'shell', call_id: 'c1', arguments: '{}' } },\n    { timestamp: 't', type: 'response_item', payload: { type: 'function_call_output', call_id: 'c1', output: 'out' } },\n    { timestamp: 't', type: 'response_item', payload: { type: 'message', role: 'assistant', content: 'hi' } },\n  ];\n  const msgs = tr.reconstructMessages(items, items.length);\n  expect(msgs).toEqual([\n    { role: 'system', content: 'sys' },\n    { role: 'assistant', content: null, tool_calls: [{ id: 'c1', type: 'function', function: { name: 'shell', arguments: '{}' } }] },\n    { role: 'tool', tool_call_id: 'c1', content: 'out' },\n    { role: 'assistant', content: 'hi' },\n  ]);\n});\n\ntest('createChildSpans span structure + timestamps + status', () => {\n  const started = tr.findTaskStartedNs(turn)!;\n  const complete = tr.findTaskCompleteNs(turn)!;\n  tr.createChildSpans({ spanId: 'root' }, turn, 'gpt-x');\n  // 1 assistant message -> 1 LLM span; 2 function_calls -> 2 TOOL spans\n  const llm = spanCalls.filter((c) => c.opts.name === 'llm_call');\n  const tools = spanCalls.filter((c) => c.opts.name.startsWith('tool_'));\n  expect(llm.length).toBe(1);\n  expect(tools.length).toBe(2);\n  // LLM first span starts at task_started\n  expect(llm[0].opts.startTimeNs).toBe(started);\n  expect(llm[0].opts.inputs.model).toBe('gpt-x');\n  expect(llm[0].span.setOutputs).toHaveBeenCalledWith({ choices: [{ message: { role: 'assistant', content: 'done' } }] });\n  // tool inputs parsed\n  expect(tools[0].opts.inputs).toEqual({ cmd: 'ls' });\n  expect(tools[0].opts.attributes).toEqual({ tool_name: 'shell', tool_id: 'c1' });\n  expect(tools[0].span.setOutputs).toHaveBeenCalledWith({ result: 'file1\\nfile2' });\n  // c1 success -> no setStatus; c2 failed -> setStatus ERROR with exit code\n  expect(tools[0].span.setStatus).not.toHaveBeenCalled();\n  expect(tools[1].span.setStatus).toHaveBeenCalledWith('STATUS_CODE_ERROR', expect.stringContaining('2'));\n  // all timestamps within window\n  for (const c of spanCalls) {\n    if (c.opts.startTimeNs != null) {\n      expect(c.opts.startTimeNs).toBeGreaterThanOrEqual(started);\n      expect(c.opts.startTimeNs).toBeLessThanOrEqual(complete);\n    }\n    const endArg = c.span.end.mock.calls[0]?.[0]?.endTimeNs;\n    if (endArg != null) {\n      expect(endArg).toBeGreaterThanOrEqual(started);\n      expect(endArg).toBeLessThanOrEqual(complete);\n    }\n  }\n});\n\ntest('processNotify creates spans and flushes', async () => {\n  const core = require('@mlflow/core');\n  const payload: any = { type: 'agent-turn-complete', 'thread-id': 'thr', 'turn-id': 'trn', cwd: '/x', client: 'c', 'input-messages': ['first', 'second'], 'last-assistant-message': 'the answer' };\n  await tr.processNotify(payload);\n  const root = spanCalls.find((c) => c.opts.name === 'codex_conversation');\n  const llm = spanCalls.find((c) => c.opts.name === 'llm_call');\n  expect(root.opts.inputs).toBe('second');\n  expect(root.opts.spanType).toBe('AGENT');\n  expect(root.span.setOutputs).toHaveBeenCalledWith('the answer');\n  expect(llm.opts.inputs).toEqual({ model: 'unknown', messages: [{ role: 'user', content: 'second' }] });\n  expect(llm.span.setOutputs).toHaveBeenCalledWith({ choices: [{ message: { role: 'assistant', content: 'the answer' } }] });\n  expect(traceInfo.traceMetadata['mlflow.trace.session']).toBe('thr');\n  expect(traceInfo.traceMetadata['mlflow.trace.user']).toBeDefined();\n  expect(core.flushTraces).toHaveBeenCalled();\n});\n\ntest('processNotify no-op on empty input-messages', async () => {\n  const core = require('@mlflow/core');\n  core.flushTraces.mockClear();\n  const payload: any = { type: 'x', 'thread-id': 't', 'turn-id': 't', cwd: '/', client: 'c', 'input-messages': [], 'last-assistant-message': 'a' };\n  await tr.processNotify(payload);\n  expect(spanCalls.length).toBe(0);\n  expect(core.flushTraces).not.toHaveBeenCalled();\n});\n"],"version":3}
