CAAC,GAAG;gBACtB,WAAW,EAAE,KAAK,CAAC,OAAO,CAAC;gBAC3B,MAAM,EAAE,EAAE,KAAK,EAAE,QAAQ,EAAE;aAC5B,CAAC,CAAC;YACH,OAAO,CAAC,UAAU,CAAC;gBACjB,OAAO,EAAE,CAAC,EAAE,OAAO,EAAE,EAAE,IAAI,EAAE,WAAW,EAAE,OAAO,EAAE,EAAE,CAAC;aACvD,CAAC,CAAC;YACH,OAAO,CAAC,GAAG,CAAC,EAAE,SAAS,EAAE,KAAK,CAAC,KAAK,CAAC,EAAE,CAAC,CAAC;YAEzC,UAAU,GAAG,KAAK,CAAC;QACrB,CAAC;aAAM,IAAI,OAAO,CAAC,IAAI,KAAK,eAAe,EAAE,CAAC;YAC5C,MAAM,MAAM,GAAG,OAAO,CAAC,OAAO,IAAI,EAAE,CAAC;YACrC,MAAM,YAAY,GAAG,OAAO,CAAC,IAAI,IAAI,SAAS,CAAC;YAC/C,MAAM,OAAO,GAAG,IAAA,+BAAkB,EAAC,GAAG,CAAC,SAAS,CAAC,CAAC;YAClD,MAAM,KAAK,GAAG,gBAAgB,CAAC,MAAM,CAAC,IAAI,IAAI,CAAC;YAE/C,MAAM,QAAQ,GAAG,IAAA,gBAAS,EAAC;gBACzB,IAAI,EAAE,QAAQ,YAAY,EAAE;gBAC5B,MAAM,EAAE,UAAU;gBAClB,QAAQ,EAAE,eAAQ,CAAC,IAAI;gBACvB,WAAW,EAAE,KAAK,CAAC,OAAO,CAAC;gBAC3B,MAAM,EAAE,cAAc,CAAC,OAAO,CAAC,SAAS,CAAC;gBACzC,UAAU,EAAE;oBACV,SAAS,EAAE,YAAY;oBACvB,OAAO,EAAE,MAAM;iBAChB;aACF,CAAC,CAAC;YACH,QAAQ,CAAC,UAAU,CAAC,EAAE,MAAM,EAAE,WAAW,CAAC,MAAM,CAAC,IAAI,EAAE,EAAE,CAAC,CAAC;YAE3D,MAAM,MAAM,GAAG,YAAY,CAAC,MAAM,CAAC,CAAC;YACpC,IAAI,MAAM,IAAI,MAAM,CAAC,MAAM,EAAE,CAAC;gBAC5B,QAAQ,CAAC,SAAS,CAChB,qBAAc,CAAC,KAAK,EACpB,iCAAiC,MAAM,CAAC,QAAQ,EAAE,CACnD,CAAC;YACJ,CAAC;YAED,QAAQ,CAAC,GAAG,CAAC,EAAE,SAAS,EAAE,KAAK,CAAC,KAAK,CAAC,EAAE,CAAC,CAAC;QAC5C,CAAC;aAAM,IAAI,OAAO,CAAC,IAAI,KAAK,sBAAsB,EAAE,CAAC;YACnD,YAAY,GAAG,IAAA,+BAAkB,EAAC,GAAG,CAAC,SAAS,CAAC,CAAC;QACnD,CAAC;IACH,CAAC;AACH,CAAC;AAED;;;GAGG;AACI,KAAK,UAAU,aAAa,CAAC,OAAsB;IACxD,MAAM,aAAa,GAAG,OAAO,CAAC,gBAAgB,CAAC,IAAI,EAAE,CAAC;IACtD,IAAI,aAAa,CAAC,MAAM,KAAK,CAAC,EAAE,CAAC;QAC/B,OAAO;IACT,CAAC;IAED,iBAAiB,EAAE,CAAC;IAEpB,MAAM,SAAS,GAAG,aAAa,CAAC,aAAa,CAAC,MAAM,GAAG,CAAC,CAAC,CAAC;IAC1D,MAAM,aAAa,GAAG,OAAO,CAAC,wBAAwB,CAAC,CAAC;IAExD,uEAAuE;IACvE,MAAM,QAAQ,GAAG,IAAA,gBAAS,EAAC;QACzB,IAAI,EAAE,oBAAoB;QAC1B,QAAQ,EAAE,eAAQ,CAAC,KAAK;QACxB,MAAM,EAAE,SAAS;KAClB,CAAC,CAAC;IAEH,8DAA8D;IAC9D,MAAM,OAAO,GAAG,IAAA,gBAAS,EAAC;QACxB,IAAI,EAAE,UAAU;QAChB,MAAM,EAAE,QAAQ;QAChB,QAAQ,EAAE,eAAQ,CAAC,GAAG;QACtB,MAAM,EAAE;YACN,KAAK,EAAE,SAAS;YAChB,QAAQ,EAAE,CAAC,EAAE,IAAI,EAAE,MAAM,EAAE,OAAO,EAAE,SAAS,EAAE,CAAC;SACjD;KACF,CAAC,CAAC;IACH,OAAO,CAAC,UAAU,CAAC;QACjB,OAAO,EAAE,CAAC,EAAE,OAAO,EAAE,EAAE,IAAI,EAAE,WAAW,EAAE,OAAO,EAAE,aAAa,EAAE,EAAE,CAAC;KACtE,CAAC,CAAC;IACH,OAAO,CAAC,GAAG,EAAE,CAAC;IAEd,sCAAsC;IACtC,IAAI,CAAC;QACH,MAAM,YAAY,GAAG,2BAAoB,CAAC,WAAW,EAAE,CAAC;QACxD,MAAM,KAAK,GAAG,YAAY,CAAC,QAAQ,CAAC,QAAQ,CAAC,OAAO,CAAC,CAAC;QACtD,IAAI,KAAK,EAAE,CAAC;YACV,KAAK,CAAC,IAAI,CAAC,aAAa,GAAG;gBACzB,GAAG,KAAK,CAAC,IAAI,CAAC,aAAa;gBAC3B,CAAC,uBAAgB,CAAC,aAAa,CAAC,EAAE,OAAO,CAAC,WAAW,CAAC;gBACtD,CAAC,uBAAgB,CAAC,UAAU,CAAC,EAAE,OAAO,CAAC,GAAG,CAAC,IAAI,IAAI,OAAO;aAC3D,CAAC;QACJ,CAAC;IACH,CAAC;IAAC,MAAM,CAAC;QACP,4CAA4C;IAC9C,CAAC;IAED,QAAQ,CAAC,UAAU,CAAC,aAAa,CAAC,CAAC;IACnC,QAAQ,CAAC,GAAG,EAAE,CAAC;IAEf,MAAM,IAAA,kBAAW,GAAE,CAAC;AACtB,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/codex/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing logic for Codex rollout transcripts and notifications.\n *\n * This module turns a Codex turn (a slice of rollout records) into MLflow\n * spans, and processes `agent-turn-complete` notification payloads.\n */\n\nimport {\n  init,\n  startSpan,\n  flushTraces,\n  SpanType,\n  SpanStatusCode,\n  TraceMetadataKey,\n  InMemoryTraceManager,\n  type LiveSpan,\n} from '@mlflow/core';\nimport {\n  buildToolResultMap,\n  extractTextFromContent,\n  parseTimestampToNs,\n} from './transcript';\nimport type { ChatMessage, NotifyPayload, RolloutLine } from './types';\n\n// SDK initialization state.\nlet initialized = false;\n\n/**\n * Best-effort initialization of the MLflow SDK from environment variables.\n * Never throws; tracing simply becomes a no-op if configuration is missing.\n */\nfunction ensureInitialized(): void {\n  if (initialized) {\n    return;\n  }\n  const trackingUri = process.env.MLFLOW_TRACKING_URI;\n  const experimentId = process.env.MLFLOW_EXPERIMENT_ID;\n  if (!trackingUri) {\n    return;\n  }\n  try {\n    init({ trackingUri, experimentId });\n    initialized = true;\n  } catch {\n    // Ignore initialization failures; spans will be no-ops.\n  }\n}\n\n/**\n * Returns the nanosecond timestamp of the task_started event_msg in the turn,\n * or null if no such event exists.\n */\nexport function findTaskStartedNs(turn: RolloutLine[]): number | null {\n  for (const rec of turn) {\n    if (rec.type === 'event_msg' && rec.payload.type === 'task_started') {\n      return parseTimestampToNs(rec.timestamp);\n    }\n  }\n  return null;\n}\n\n/**\n * Returns the nanosecond timestamp of the task_complete event_msg in the turn,\n * or null if no such event exists.\n */\nexport function findTaskCompleteNs(turn: RolloutLine[]): number | null {\n  for (const rec of turn) {\n    if (rec.type === 'event_msg' && rec.payload.type === 'task_complete') {\n      return parseTimestampToNs(rec.timestamp);\n    }\n  }\n  return null;\n}\n\n/**\n * Scans exec_command_end event_msg records in the turn and returns a map from\n * call_id to { failed, exitCode }. A tool is marked failed when its status is\n * 'failed' or its exit_code is non-zero.\n */\nexport function buildToolStatuses(\n  turn: RolloutLine[],\n): Record<string, { failed: boolean; exitCode: number }> {\n  const statuses: Record<string, { failed: boolean; exitCode: number }> = {};\n  for (const rec of turn) {\n    if (rec.type === 'event_msg' && rec.payload.type === 'exec_command_end') {\n      const payload = rec.payload;\n      const callId = payload.call_id;\n      if (typeof callId !== 'string') {\n        continue;\n      }\n      const exitCode = typeof payload.exit_code === 'number' ? payload.exit_code : 0;\n      const failed = payload.status === 'failed' || exitCode !== 0;\n      statuses[callId] = { failed, exitCode };\n    }\n  }\n  return statuses;\n}\n\n/**\n * Parses a function_call `arguments` JSON string into an object. Returns an\n * empty object for missing or unparseable arguments.\n */\nfunction parseArguments(args: unknown): Record<string, unknown> {\n  if (args == null || args === '') {\n    return {};\n  }\n  if (typeof args === 'object') {\n    return args as Record<string, unknown>;\n  }\n  if (typeof args !== 'string') {\n    return {};\n  }\n  try {\n    const parsed = JSON.parse(args);\n    return parsed != null && typeof parsed === 'object'\n      ? (parsed as Record<string, unknown>)\n      : {};\n  } catch {\n    return {};\n  }\n}\n\n/**\n * Converts transcript response_item records (up to but not including\n * uptoIndex) into OpenAI chat-format messages. Messages whose extracted text\n * is empty or whitespace-only are skipped.\n */\nexport function reconstructMessages(items: RolloutLine[], uptoIndex: number): ChatMessage[] {\n  const messages: ChatMessage[] = [];\n  const end = Math.min(uptoIndex, items.length);\n\n  for (let i = 0; i < end; i++) {\n    const rec = items[i];\n    if (rec.type !== 'response_item') {\n      continue;\n    }\n    const payload = rec.payload;\n\n    switch (payload.type) {\n      case 'message': {\n        const text = extractTextFromContent(payload.content);\n        if (text.trim().length === 0) {\n          break;\n        }\n        if (payload.role === 'user') {\n          messages.push({ role: 'user', content: text });\n        } else if (payload.role === 'assistant') {\n          messages.push({ role: 'assistant', content: text });\n        } else if (payload.role === 'developer') {\n          messages.push({ role: 'system', content: text });\n        }\n        break;\n      }\n      case 'function_call': {\n        messages.push({\n          role: 'assistant',\n          content: null,\n          tool_calls: [\n            {\n              id: payload.call_id ?? '',\n              type: 'function',\n              function: {\n                name: payload.name ?? '',\n                arguments: typeof payload.arguments === 'string' ? payload.arguments : '',\n              },\n            },\n          ],\n        });\n        break;\n      }\n      case 'function_call_output': {\n        const output = buildToolResultMap([rec])[payload.call_id ?? ''] ?? '';\n        if (output.trim().length === 0) {\n          break;\n        }\n        messages.push({\n          role: 'tool',\n          tool_call_id: payload.call_id ?? '',\n          content: output,\n        });\n        break;\n      }\n      default:\n        break;\n    }\n  }\n\n  return messages;\n}\n\n/**\n * Creates MLflow LLM and TOOL child spans from a transcript turn, parented to\n * the given parent span.\n */\nexport function createChildSpans(\n  parent: { spanId: string },\n  turn: RolloutLine[],\n  model: string,\n): void {\n  const taskStartedNs = findTaskStartedNs(turn);\n  const taskCompleteNs = findTaskCompleteNs(turn);\n  const toolResults = buildToolResultMap(turn);\n  const toolStatuses = buildToolStatuses(turn);\n\n  // Map each call_id to the timestamp of its function_call_output record.\n  const outputTsByCallId: Record<string, number | null> = {};\n  for (const rec of turn) {\n    if (rec.type === 'response_item' && rec.payload.type === 'function_call_output') {\n      const callId = rec.payload.call_id;\n      if (typeof callId === 'string') {\n        outputTsByCallId[callId] = parseTimestampToNs(rec.timestamp);\n      }\n    }\n  }\n\n  // Clamp timestamps into the [task_started, task_complete] window.\n  const clamp = (ns: number | null | undefined): number | undefined => {\n    if (ns == null) {\n      return taskStartedNs ?? undefined;\n    }\n    let value = ns;\n    if (taskStartedNs != null && value < taskStartedNs) {\n      value = taskStartedNs;\n    }\n    if (taskCompleteNs != null && value > taskCompleteNs) {\n      value = taskCompleteNs;\n    }\n    return value;\n  };\n\n  // The parent is typed structurally; at runtime callers pass a real LiveSpan.\n  const parentSpan = parent as unknown as LiveSpan;\n\n  let isFirstLlm = true;\n  let lastOutputNs: number | null = null;\n\n  for (let i = 0; i < turn.length; i++) {\n    const rec = turn[i];\n    if (rec.type !== 'response_item') {\n      continue;\n    }\n    const payload = rec.payload;\n\n    if (payload.type === 'message' && payload.role === 'assistant') {\n      const content = extractTextFromContent(payload.content);\n      const messages = reconstructMessages(turn, i);\n      const startNs = isFirstLlm ? taskStartedNs : lastOutputNs;\n      const endNs = parseTimestampToNs(rec.timestamp);\n\n      const llmSpan = startSpan({\n        name: 'llm_call',\n        parent: parentSpan,\n        spanType: SpanType.LLM,\n        startTimeNs: clamp(startNs),\n        inputs: { model, messages },\n      });\n      llmSpan.setOutputs({\n        choices: [{ message: { role: 'assistant', content } }],\n      });\n      llmSpan.end({ endTimeNs: clamp(endNs) });\n\n      isFirstLlm = false;\n    } else if (payload.type === 'function_call') {\n      const callId = payload.call_id ?? '';\n      const functionName = payload.name ?? 'unknown';\n      const startNs = parseTimestampToNs(rec.timestamp);\n      const endNs = outputTsByCallId[callId] ?? null;\n\n      const toolSpan = startSpan({\n        name: `tool_${functionName}`,\n        parent: parentSpan,\n        spanType: SpanType.TOOL,\n        startTimeNs: clamp(startNs),\n        inputs: parseArguments(payload.arguments),\n        attributes: {\n          tool_name: functionName,\n          tool_id: callId,\n        },\n      });\n      toolSpan.setOutputs({ result: toolResults[callId] ?? '' });\n\n      const status = toolStatuses[callId];\n      if (status && status.failed) {\n        toolSpan.setStatus(\n          SpanStatusCode.ERROR,\n          `Command failed with exit code ${status.exitCode}`,\n        );\n      }\n\n      toolSpan.end({ endTimeNs: clamp(endNs) });\n    } else if (payload.type === 'function_call_output') {\n      lastOutputNs = parseTimestampToNs(rec.timestamp);\n    }\n  }\n}\n\n/**\n * Processes an `agent-turn-complete` notification payload, creating MLflow\n * spans for the completed turn.\n */\nexport async function processNotify(payload: NotifyPayload): Promise<void> {\n  const inputMessages = payload['input-messages'] ?? [];\n  if (inputMessages.length === 0) {\n    return;\n  }\n\n  ensureInitialized();\n\n  const lastInput = inputMessages[inputMessages.length - 1];\n  const lastAssistant = payload['last-assistant-message'];\n\n  // AGENT root span with the last input message as its raw string input.\n  const rootSpan = startSpan({\n    name: 'codex_conversation',\n    spanType: SpanType.AGENT,\n    inputs: lastInput,\n  });\n\n  // A single LLM child span representing the turn's model call.\n  const llmSpan = startSpan({\n    name: 'llm_call',\n    parent: rootSpan,\n    spanType: SpanType.LLM,\n    inputs: {\n      model: 'unknown',\n      messages: [{ role: 'user', content: lastInput }],\n    },\n  });\n  llmSpan.setOutputs({\n    choices: [{ message: { role: 'assistant', content: lastAssistant } }],\n  });\n  llmSpan.end();\n\n  // Attach session/user trace metadata.\n  try {\n    const traceManager = InMemoryTraceManager.getInstance();\n    const trace = traceManager.getTrace(rootSpan.traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        [TraceMetadataKey.TRACE_SESSION]: payload['thread-id'],\n        [TraceMetadataKey.TRACE_USER]: process.env.USER || 'codex',\n      };\n    }\n  } catch {\n    // Metadata is best-effort; ignore failures.\n  }\n\n  rootSpan.setOutputs(lastAssistant);\n  rootSpan.end();\n\n  await flushTraces();\n}\n"],"version":3}
